import{_ as o,c as e,o as n,ag as s}from"./chunks/framework.Cycwnjj0.js";const r="/assets/select-desired-table-for-adding-columns.DVuUT-Nk.webp",a="/assets/opened-table-with-all-customization-options.CcA5ncnC.webp",i="/assets/add-column-custom-css-add-products.xqACSuRo.webp",c="/assets/edit-and-design-mode.DXJYRC0-.webp",p="/assets/shortcode.Bx6tfUyn.webp",g="/assets/drag-_-drop-button.BmYEflAH.webp",l="/assets/edit-title_allignment-for-each-column-and-row-png.BevyLB5O.webp",u="/assets/delete-button.BaSbTJin.webp",d="/assets/edit-title.DaCi0pe9.webp",h="/assets/edit-table-info-popup-page.BtVilcG6.webp",m="/assets/preview-save-changes-button.CxdpBWiz.webp",A=JSON.parse('{"title":"Customization of Product Tables","description":"","frontmatter":{},"headers":[],"relativePath":"guide/product-tables-module/customization-of-product-tables.md","filePath":"guide/product-tables-module/customization-of-product-tables.md"}'),b={name:"guide/product-tables-module/customization-of-product-tables.md"};function y(f,t,w,_,T,P){return n(),e("div",null,[...t[0]||(t[0]=[s('<h1 id="customization-of-product-tables" tabindex="-1">Customization of Product Tables <a class="header-anchor" href="#customization-of-product-tables" aria-label="Permalink to &quot;Customization of Product Tables&quot;">​</a></h1><p>AzonPress offers excellent customization features, making it easy to customize according to your needs. This article will guide you through <strong>Customizing Product Tables</strong> with <strong>AzonPress</strong> for <strong>Amazon products</strong> on your <strong>WordPress</strong> website.</p><h2 id="how-to-customize-a-product-table" tabindex="-1">How To Customize A Product Table <a class="header-anchor" href="#how-to-customize-a-product-table" aria-label="Permalink to &quot;How To Customize A Product Table&quot;">​</a></h2><p>To learn how to customize the information displayed in your Product table with AzonPress, follow the steps with the screenshots below –</p><p>First, go to <strong>Amazon Products</strong> from the <strong>WordPress Sidebar</strong> or <strong>Product Tables</strong> from the <strong>Amazon</strong> dropdown in the top right corner of the <strong>AzonPress Navbar</strong>.</p><p>Now, select the desired <strong>Table</strong> where you want to add columns and click on the <strong>Pencil Icon.</strong></p><p>If you do not have any existing <strong>Product Tables</strong>, you can <strong>create a new Product Table</strong>.</p><p><img src="'+r+'" alt="Select desired table"></p><p>Now, you can see that your desired product table has been opened in your backend.</p><p><img src="'+a+'" alt="Opened Table with all customization options"></p><p><strong>Here is a brief explanation of all the settings options on the pop-up page given below –</strong></p><p>You can <strong>Add Columns</strong> by clicking on the <strong>+ Add Column</strong> button. You can do any custom design in your table, by pressing the <strong>Custom CSS</strong> button.</p><p>Also, you can add more products by clicking the <strong>+ Add Product</strong> button and it will take you to the product search pop-up page again.</p><p><img src="'+i+'" alt="Add column custom css add products"></p><p>Two more options are available just above the left side of the page, and these are <strong>Edit Mode</strong> and <strong>Design Mode</strong>. You can use those options to change it anywhere or create a custom design for the table.</p><ul><li>To change the design of your table, click on the <strong>Design Mode</strong> button and the <strong>Settings</strong> bar will appear on the right side.</li><li>Then, you can choose the library style, color, pagination number, and feature needed for your table from the <strong>Styling library</strong>, <strong>Color Skin</strong>, <strong>Product Table Pagination</strong>, and <strong>Styling Feature</strong> settings options.</li></ul><p><em>&quot;For example, you can see in the picture below that I have selected all fields of the Styling Feature and customized the table according to my choice using the settings options.&quot;</em></p><p><img src="'+c+'" alt="Edit and design mode"></p><p>You can use the <strong>Shortcode</strong> in the top left corner to use this Product table on any <strong>Post/Page</strong> in your WordPress site.</p><p><img src="'+p+'" alt="Shortcode"></p><p>Plus, with the help of the <strong>Drag and Drop</strong> button, you can move your columns right and left, and rows up and down smoothly at any time.</p><p><img src="'+g+'" alt="Drag Drop button"></p><p>Also, you can <strong>edit</strong> the <strong>title</strong> and <strong>alignment of</strong> your <strong>columns</strong> and <strong>only</strong> the <strong>title for</strong> your <strong>rows</strong> by clicking the <strong>Pencil Icon</strong> right next to each column and row.</p><p><img src="'+l+'" alt="Edit Title Alignment for each Column and Row"></p><p>You can <strong>Delete</strong> any existing row by clicking the <strong>Trash Icon</strong>.</p><p><img src="'+u+'" alt="Delete button"></p><p>You can change the <strong>Title</strong> of <strong>Product Tables</strong> anytime by clicking on the <strong>Pencil Icon</strong> in the top left corner.</p><p><img src="'+d+'" alt="Edit Table Title"></p><p>A new pop-up window will appear where you can <strong>change</strong> the <strong>Table Title</strong> and <strong>provide</strong> a <strong>Table Description</strong>. Then, click the <strong>Update Info</strong> button to save the changes.</p><p><img src="'+h+'" alt="Edit table Info popup page"></p><p>Once you are done, click the <strong>Save Changes</strong> button, and your tables will be ready to display.</p><p>You can see the preview of your table by clicking the <strong>Preview</strong> button in the top right corner.</p><p><img src="'+m+'" alt="Preview save changes button"></p><h2 id="customization-through-appearance-settings" tabindex="-1">Customization Through Appearance Settings <a class="header-anchor" href="#customization-through-appearance-settings" aria-label="Permalink to &quot;Customization Through Appearance Settings&quot;">​</a></h2><p>To learn about customizing tables through Appearance Settings, read this <a href="/guide/miscellaneous/appearance-settings.html">Documentation</a>.</p><p>This is how you can customize the product table as per your proper design!</p><p>If you have any further questions, concerns, or suggestions, please do not hesitate to contact our support team. Thank you.</p><hr>',38)])])}const C=o(b,[["render",y]]);export{A as __pageData,C as default};
